const links=[...document.querySelectorAll('a')].map(a=>a.href);
const out=[document.body.innerText.slice(0,1500)];
for(const l of links){const t=await fetch(l).then(r=>r.text());const d=new DOMParser().parseFromString(t,'text/html');out.push(l+' :: '+d.body.innerText.replace(/\s+/g,' ').slice(0,600));}
out.join('\n')

const links=[...document.querySelectorAll('a')].map(a=>a.href).filter(h=>h.includes('camera?'));
const out=[];
for(const l of links){const t=await fetch(l).then(r=>r.text());const d=new DOMParser().parseFromString(t,'text/html');out.push(d.body.textContent.replace(/\s+/g,' ').replace(/.*All cameras/,'').slice(0,200));}
out.join('\n')
